package local.generalsmc.client;
import local.generalsmc.*;
import local.generalsmc.nativebridge.*;
import net.minecraft.client.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.phys.Vec3;
import net.minecraft.client.gui.components.Button;
import java.util.*;
import java.util.concurrent.*;

/** Targeted new feedback gate in the real remapped player mod, without unrelated gameplay loops. */
final class NativeNetworkPolishBench {
    static int stage,age,victim;static boolean sawDeath;static CompletableFuture<?> work;
    static final Vec3 DEATH=new Vec3(14.5,64,13.5);
    static void next(int n){stage=n;age=0;GeneralsMod.LOG.info("Network polish case {}",n);}
    static boolean tick(Minecraft mc,List<String> checks)throws Exception{
        age++;if(age>1000)throw new IllegalStateException("New feedback timeout "+stage);var v=NativeWorldView.current;
        if(stage==0){NativeBlastBench.tick(mc,checks);if(NativeBlastBench.done){NativeMusicBench.during(mc,checks);NativeRtsController.toggle();
            work=CompletableFuture.runAsync(()->{var l=mc.getSingleplayerServer().getLevel(GeneralsMod.ARENA);l.setBlock(new BlockPos(12,64,12),SiteBlocks.START.defaultBlockState(),3);l.setBlock(new BlockPos(18,64,12),SiteBlocks.OIL.defaultBlockState(),3);l.setBlock(new BlockPos(-40,64,24),SiteBlocks.START.defaultBlockState(),3);WorldSiteStore.get(l).putStart(new BlockPos(-40,64,24),1,"FactionChina",1,1);mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID()).teleportTo(l,12.5,67,32.5,Set.of(),180,12,false);},mc.getSingleplayerServer());next(1);}}
        else if(stage==1&&age>40&&work.isDone()){work.join();if(!(mc.level.getBlockEntity(new BlockPos(12,64,12)) instanceof SiteMarkerEntity)||!(mc.level.getBlockEntity(new BlockPos(18,64,12)) instanceof SiteMarkerEntity))throw new IllegalStateException("Marker renderer bodies not tracked by Minecraft");NativeMusicBench.during(mc,checks);Screenshot.grab(mc.gameDirectory,"102-feedback-marker-beacons.png",mc.getMainRenderTarget(),c->{});checks.add("Placed start/oil/supply markers use actual Minecraft-tracked block entities and original coloured beacon renderers, with32pixel inventory icons and no scanning tickers");NativeReleaseBench.spawn(v,"AmericaVehicleHumvee",DEATH);next(2);}
        else if(stage==2&&age>30){victim=NativeOctoberBench.at(v,"AmericaVehicleHumvee",DEATH).id();v.session.send("TEST_DAMAGE "+victim+" 1000000");next(3);}
        else if(stage==3){if(v.state.exportedParticles()>0&&v.scene!=null&&v.scene.batches().stream().anyMatch(b->b.actor()==0xe0000000&&v.origin.world(b.vertices()[0],b.vertices()[1],b.vertices()[2]).distanceTo(DEATH)<10)){sawDeath=true;Screenshot.grab(mc.gameDirectory,"103-feedback-minecraft-vehicle-death.png",mc.getMainRenderTarget(),c->{});}if(age>90){if(!sawDeath)throw new IllegalStateException("Original Humvee death particles absent in normal Minecraft mode");checks.add("Destroying an actual original Humvee exports its own nearby death particles into Minecraft mode with the Minecraft camera, without a generic test FX substitution");NativeRtsController.toggle();NativeMusicBench.during(mc,checks);NativeRtsController.stop();mc.setScreen(new NativeLobbyScreen(null));NativeSetupBench.click(mc.screen,"Создать комнату");next(4);}}
        else if(stage==4&&NativeNetworkClient.lobby!=null&&NativeNetworkClient.lobby.members().stream().allMatch(NativeNetworkServer.Member::ready)&&!NativeNetworkClient.lobby.preparing()){
            ((NativeLobbyScreen)mc.screen).tick();next(40);
        }else if(stage==40&&age>10){var starts=mc.screen.children().stream().filter(w->w instanceof Button b&&b.getMessage().getString().startsWith("Старт: ")).map(w->(Button)w).toList();if(starts.size()!=2||starts.get(0).getX()!=starts.get(1).getX())throw new IllegalStateException("Player and NPC start controls use different columns");NativeSetupBench.bounds(mc.screen);Screenshot.grab(mc.gameDirectory,"104-feedback-aligned-lobby.png",mc.getMainRenderTarget(),c->{});mc.screen.mouseScrolled(mc.screen.width/2.0,80,0,-4);next(41);
        }else if(stage==41&&age>10){NativeSetupBench.bounds(mc.screen);var remove=mc.screen.children().stream().filter(w->w instanceof Button b&&b.getMessage().getString().equals("Убрать NPC")).map(w->(Button)w).findFirst().orElseThrow();if(!remove.visible)throw new IllegalStateException("NPC header is inaccessible at maximum compact scroll");Screenshot.grab(mc.gameDirectory,"104-feedback-aligned-npc.png",mc.getMainRenderTarget(),c->{});checks.add("The real compact lobby aligns human/NPC faction, colour, team and start controls, and keeps difficulty/removal visible at the end of compact scrolling");NativeSetupBench.click(mc.screen,"Сложность: средняя");next(42);
        }else if(stage==42&&NativeNetworkClient.lobby.starts().stream().anyMatch(s->s.difficulty()==2)&&age>5){var b=mc.screen.children().stream().filter(w->w instanceof Button button&&button.getMessage().getString().equals("Сложность: сложная")).map(w->(Button)w).findFirst().orElseThrow();if(!b.mouseClicked(b.getX()+3,b.getY()+3,1))throw new IllegalStateException("NPC difficulty refused right click");next(43);
        }else if(stage==43&&NativeNetworkClient.lobby.starts().stream().anyMatch(s->s.difficulty()==1)&&age>5){NativeSetupBench.click(mc.screen,"Убрать NPC");next(44);
        }else if(stage==44&&NativeNetworkClient.lobby.starts().stream().noneMatch(s->s.difficulty()>=0)&&age>5){NativeSetupBench.click(mc.screen,"+ Добавить NPC");next(45);
        }else if(stage==45&&NativeNetworkClient.lobby.starts().stream().anyMatch(s->s.difficulty()>=0)&&age>5){checks.add("Actual compact lobby buttons change NPC difficulty forward/backward, remove its assignment and add a new NPC through authenticated server requests");NativeSetupBench.click(mc.screen,"Ресурсы");if(!(mc.screen instanceof StartMapScreen map)||!map.resources)throw new IllegalStateException("Supply button opened start selection");next(5);
        }else if(stage==5&&age>20&&NativeMapFeedbackBench.tick(mc,checks)){if(NativeNetworkClient.mapPoints.stream().noneMatch(p->p.kind().equals("supply"))||NativeNetworkClient.mapPoints.stream().noneMatch(p->p.kind().equals("oil")))throw new IllegalStateException("Resource map did not receive actual marker sites");Screenshot.grab(mc.gameDirectory,"105-feedback-resource-map.png",mc.getMainRenderTarget(),c->{});mc.screen.onClose();NativeSetupBench.click(mc.screen,"Позиции");if(!(mc.screen instanceof StartMapScreen map)||map.resources)throw new IllegalStateException("Starts open resources");checks.add("Separate actual supply/oil and start map buttons receive persisted world resources through Fabric and open the correct map modes");mc.screen.onClose();NativeNetworkClient.leave();next(6);}
        else if(stage==6&&age>20&&NativeNetworkClient.lobby==null){var stock=NativeProfiles.active();var legacy=new NativeProfiles.Profile(UUID.randomUUID().toString(),"Rise of the Reds","C:/Games/ROTR","C:/Games/Generals","C:/Games/ROTR",true,stock.factions(),stock.colors(),"2026-10-18T11:50:33Z","old-engine");java.nio.file.Files.writeString(NativeProfiles.root().resolve("profiles.json"),GeneralsMod.JSON.toJson(new NativeProfiles.Registry(1,legacy.id(),List.of(stock,legacy))));mc.setScreen(new GeneralsSetupScreen(null));NativeSetupBench.click(mc.screen,"Обновить данные игры");next(7);}
        else if(stage==7&&mc.screen instanceof GeneralsSetupScreen&&NativeProfiles.active()!=null&&NativeProfiles.active().modified()){
            var p=NativeProfiles.active();if(!p.name().equals("Rise of the Reds"))throw new IllegalStateException("Legacy ROTR profile changed its name: "+p.name());GeneralsSetupScreen.useProfile(p);var russian=p.factions().stream().filter(f->p.factionNames().getOrDefault(f,"").contains("Russian")).findFirst().orElseThrow();if(!GeneralsSetupScreen.friendly(russian).equals("Россия"))throw new IllegalStateException("ROTR alias shows a vanilla US general");NativeSetupBench.click(mc.screen,"Начать RTS здесь");((NativeLaunchScreen)mc.screen).faction=russian;Screenshot.grab(mc.gameDirectory,"106-feedback-rotr-factions.png",mc.getMainRenderTarget(),c->{});NativeSetupBench.click(mc.screen,"Начать");next(8);
        }else if(stage==8&&v!=null&&v.state!=null&&v.state.terrainColumns()>=4096&&v.state.frame()>180&&v.scene!=null&&!v.scene.batches().isEmpty()&&age>80){if(v.state.objects().stream().noneMatch(a->a.owner()==2&&a.structure()&&a.template().toLowerCase(Locale.ROOT).contains("russia")))throw new IllegalStateException("Wrong ROTR base spawned");NativeMusicBench.during(mc,checks);Screenshot.grab(mc.gameDirectory,"107-feedback-rotr-minecraft.png",mc.getMainRenderTarget(),c->{});checks.add("An actual legacy ROTR profile with vanilla faction IDs refreshes through the ordinary mod UI, replaces stale data and displays Russia from its source alias and starts/render its original Russian base on Minecraft terrain");return true;}
        return false;
    }
}
